708	        saved = await firstValueFrom(
709	          this.http.put<SettingsView>(
710	            `${url}/policy-date`,
711	            { policyDate: policyDate === '' ? null : policyDate },
712	            this.session.headers(),
713	          ),
714	        );
715	        this.policyDateEdited = false;
