718	        saved = await firstValueFrom(
719	          this.http.put<SettingsView>(
720	            `${url}/period-numbering-from`,
721	            { periodNumberingFrom: periodNumberingFrom === '' ? null : periodNumberingFrom },
722	            this.session.headers(),
